def binary_search(arr: list[int], target: int) -> int:
    low, high = 0, len(arr) - 1

    while low <= high:
        mid = (low + high) // 2
        val = arr[mid]
        if val == target:
            return mid
        elif val < target:
            low = mid + 1
        else:
            high = mid - 1

    return -1

if __name__ == '__main__':
    nums = [2, 5, 8, 12, 16, 23, 38, 56, 72, 91]
    print(f"Index of 23: {binary_search(nums, 23)}")

